use std::io::Write;
use std::path::PathBuf;
use std::process::{Command,Output,Stdio};
use std::sync::atomic::{AtomicU64,Ordering};
const BIN:&str=env!("CARGO_BIN_EXE_lfz");
static NEXT:AtomicU64=AtomicU64::new(0);
struct Work(PathBuf);
impl Work {
 fn new()->Self {let p=PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("Temp/T16-B-tooling/tests").join(format!("{}-{}",std::process::id(),NEXT.fetch_add(1,Ordering::Relaxed)));std::fs::create_dir_all(&p).unwrap();Self(p)}
 fn file(&self,name:&str,body:&str)->String {let p=self.0.join(name);std::fs::write(&p,format!("#42\n{body}")).unwrap();p.to_str().unwrap().into()}
 fn run(&self,args:&[&str],stdin:&[u8])->Output {let mut c=Command::new(BIN).args(args).current_dir(&self.0).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();if let Some(mut p)=c.stdin.take(){let _=p.write_all(stdin);}let end=std::time::Instant::now()+std::time::Duration::from_secs(10);while c.try_wait().unwrap().is_none(){if std::time::Instant::now()>=end{let _=c.kill();let _=c.wait();panic!("模块check进程超时");}std::thread::sleep(std::time::Duration::from_millis(5));}c.wait_with_output().unwrap()}
}


fn fixture()->String{use std::sync::OnceLock;static P:OnceLock<String>=OnceLock::new();P.get_or_init(||{let root=PathBuf::from(env!("CARGO_MANIFEST_DIR"));let dir=root.join("Temp/T18-A-tooling/cli-fixture");std::fs::create_dir_all(&dir).unwrap();let src=dir.join("fixture.rs");let exe=dir.join("fixture.exe");std::fs::write(&src,include_str!("../src/process_control/fixture.rs")).unwrap();let r=Command::new(root.join("Temp/toolchain/cargo/bin/rustc.exe")).args(["--edition=2021","-C","opt-level=1","-C","debuginfo=0"]).arg(&src).arg("-o").arg(&exe).env("TEMP",&dir).env("TMP",&dir).output().unwrap();assert!(r.status.success(),"{}",String::from_utf8_lossy(&r.stderr));exe.to_str().unwrap().into()}).clone()}
fn call(mode:&str,args:&str,ms:u32,bytes:u32)->String{format!("exec([{:?},{:?}{}],{ms},{bytes})",fixture(),mode,args)}
#[test]fn default_disabled_and_explicit_session_enable(){let w=Work::new();let s=format!("print({}.stdout)",call("echo",",\"\",\"a b\",\"中文🙂\"",5000,1000));let r=w.run(&["-e",&s,"--json"],b"");assert_eq!(r.status.code(),Some(2));assert!(String::from_utf8_lossy(&r.stdout).contains("子进程能力未启用"));let r=w.run(&["--allow-process","-e",&s],b"");assert_eq!(r.status.code(),Some(0),"{:?}",r);assert_eq!(r.stdout,"0:\n3:a b\n10:中文🙂\n\n".as_bytes());assert!(r.stderr.is_empty());let r=w.run(&["-e",&s,"--json"],b"");assert!(String::from_utf8_lossy(&r.stdout).contains("子进程能力未启用"));}
#[test]fn captured_outputs_are_values_not_implicit_terminal_output(){let w=Work::new();let s=call("dual",",\"16384\"",5000,32768);let r=w.run(&["-e",&s,"--allow-process","--json"],b"");assert_eq!(r.status.code(),Some(0),"{:?}",r);assert_eq!(r.stdout,b"{\"ok\":true}\n");assert!(r.stderr.is_empty());let s=format!("print({}.exitCode)",call("exit",",\"7\"",5000,0));let r=w.run(&["-e",&s,"--allow-process"],b"");assert_eq!(r.stdout,b"7\n");}
#[test]fn timeout_output_limit_utf8_are_recoverable_values(){let w=Work::new();for(s,message)in[(call("sleep",",\"10000\"",20,0),"子进程执行时间上限已到"),(call("dual",",\"1024\"",5000,2047),"子进程输出超过字节上限"),(call("invalid","",5000,1),"子进程输出不是合法 UTF-8")]{let s=format!("let r=attempt(()=>{s})\nprint(r.ok)\nprint(r.error.message)");let r=w.run(&["-e",&s,"--allow-process"],b"");assert_eq!(r.status.code(),Some(0),"{:?}",r);assert!(String::from_utf8_lossy(&r.stdout).contains(message));assert!(r.stderr.is_empty());}}
#[test]fn global_deadline_inside_exec_is_not_caught(){let w=Work::new();let s=format!("attempt(()=>{})",call("sleep",",\"10000\"",5000,0));let r=w.run(&["--allow-process","--timeout-ms","20","-e",&s,"--json"],b"");assert_eq!(r.status.code(),Some(2));assert!(String::from_utf8_lossy(&r.stdout).contains("ExecutionLimitError"));assert!(r.stderr.is_empty());}
#[test]fn capability_scan_usage_code_and_argv_protection(){let w=Work::new();for cmd in ["check","test","--help","-h","--version","-V"]{let r=w.run(&[cmd,"--allow-process"],b"");assert_eq!(r.status.code(),Some(2));assert!(r.stdout.is_empty());assert!(String::from_utf8_lossy(&r.stderr).contains("子进程能力选项只适用于运行命令"));}for(args,message)in[(vec!["--allow-process","-e","","--allow-process"],"不能重复"),(vec!["--allow-process=1","--help"],"不接受值")]{let r=w.run(&args,b"");assert_eq!(r.status.code(),Some(2));assert!(String::from_utf8_lossy(&r.stderr).contains(message));}let r=w.run(&["-e","print(argv()[0])","--","--allow-process"],b"");assert_eq!(r.stdout,b"--allow-process\n");let r=w.run(&["check","-e","--allow-process","--json"],b"");assert!(String::from_utf8_lossy(&r.stdout).contains("\"mode\":\"check\""));}
#[test]fn module_inherits_same_session_permission(){let w=Work::new();let source=format!("fn go()=>{}\nexport go\n",call("stdin","",5000,1));w.file("dep.lfz",&source);let p=w.file("root.lfz","import lib from \"./dep.lfz\"\nprint(lib.go().stdout)\n");let r=w.run(&["run",&p,"--allow-process"],b"");assert_eq!(r.status.code(),Some(0),"{:?}",r);assert_eq!(r.stdout,b"0\n");let r=w.run(&["run",&p,"--json"],b"");assert_eq!(r.status.code(),Some(2));let s=String::from_utf8_lossy(&r.stdout);assert!(s.contains("子进程能力未启用"));assert!(s.contains("dep.lfz"));}
